"""Publication prose and small charts generated from the raw-backed projection."""
from pathlib import Path
import json
from html import escape
from wording import public_text

HERE=Path(__file__).resolve().parent
CASE=HERE.parent

def table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |',
                      *['| '+' | '.join(map(str,r))+' |' for r in rows]])

def write(name,text):
    p=CASE/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text.strip()+'\n')

def generate():
    d=json.loads((HERE/'summary/project.json').read_text())
    for lang in ('ko','en'):
        ko=lang=='ko';txt=lambda k,e:k if ko else e;suffix='.ko.md' if ko else '.md'
        title=txt('Case017 — 도구 호출 규칙과 업무 완주 비용','Case017 — Agent Contract–Cost Bench')
        copy=public_text(d,lang)
        intro=copy['intro']
        definition=copy['kv_intro']
        policies=copy['policy_intro']
        success=table([txt('KV 저장','KV storage'),'C0','G','N','E'],[[txt('BF16 KV (K0)','BF16 KV (K0)'),*[f"{next(g for g in d['groups'] if g['stage']=='P2' and g['kv']=='K0' and g['policy']==p)['verified']}/24" for p in ('C0','G','N','E')]],
                       [txt('NVFP4 KV (K1)','NVFP4 KV (K1)'),*[f"{next(g for g in d['groups'] if g['stage']=='P2' and g['kv']=='K1' and g['policy']==p)['verified']}/24" for p in ('C0','G','N','E')]]])
